/** A01-R00-SISDIA: imagen de S151B01SISDIA en el archivo de respaldo (campos COMP). */
public record RespaldoSistemaDia(
        String sistema,                 // 9(04)
        int csi,                        // 9(02): P680 no lo usa, fuerza 0 al cargar
        LocalDate fechaProceso, LocalDate fechaConsulta, LocalDate fechaProceso151,   // 9(08) AAAAMMDD
        int statusRegistro,
        Archivo saldos, Archivo movimientos, Archivo desglose, Archivo errores,       // X(34) + X(17)
        String baseSemanal,             // X(17)
        int statusBaseSemanal,          // A01-R00-STABDSEM: viene en el archivo, no se restaura (ver s5)
        int numArchivo, int tercerNivel,
        List<DiaArchivo> calendario) {  // OCCURS 10

    public record Archivo(String nombre, String pack) {}
    public record DiaArchivo(LocalDate fecha, long nivelArchivo, long nivelBase, int statusLog) {}
}

